//! Executable contracts generated by fixtures/generate.py.
use ondevice_coreml::{ComputeUnits, Error, Inputs, Model, Tensor, f16};
use std::path::PathBuf;

fn model(name: &str) -> Model {
    let root = PathBuf::from(
        std::env::var_os("ONDEVICE_COREML_FIXTURES")
            .expect("generate coreml/fixtures/models and set ONDEVICE_COREML_FIXTURES"),
    );
    Model::open(root.join(format!("{name}.mlmodelc"))).unwrap()
}

#[test]
fn native_multidimensional_roundtrip() {
    let values = [1., 2., 3., 4., 5., 6.];
    let tensor = Tensor::from_slice(&[2, 3], &values).unwrap();
    assert_eq!(tensor.read().data(), values);
    assert!(matches!(
        Tensor::from_slice(&[3, 3], &values),
        Err(Error::TensorShape { .. })
    ));
}

#[test]
#[ignore = "requires generated Core ML fixtures"]
fn heterogeneous_inputs_and_native_output_reuse() {
    let mut function = model("affine")
        .function(None, ComputeUnits::CpuOnly)
        .unwrap();
    assert_eq!(
        function.description().inputs["matrix"].default_shape,
        [2, 3]
    );
    assert_eq!(function.description().inputs["bias"].default_shape, [3]);
    let matrix = Tensor::from_slice(&[2, 3], &[1f32, 2., 3., 4., 5., 6.]).unwrap();
    let bias = Tensor::from_slice(&[3], &[10f32, 20., 30.]).unwrap();
    let mut inputs = Inputs::new();
    inputs.insert("matrix", &matrix).unwrap();
    inputs.insert("bias", &bias).unwrap();
    let output = function
        .predict(&inputs)
        .unwrap()
        .tensor::<f32>("output")
        .unwrap();
    assert_eq!(output.read().data(), [11., 22., 33., 14., 25., 36.]);
    let mut next = Inputs::new();
    next.insert("matrix", &output).unwrap();
    next.insert("bias", &bias).unwrap();
    drop(output);
    assert_eq!(
        function
            .predict(&next)
            .unwrap()
            .tensor::<f32>("output")
            .unwrap()
            .read()
            .data(),
        [21., 42., 63., 24., 45., 66.]
    );
}

#[test]
#[ignore = "requires generated Core ML fixtures"]
fn states_accumulate_reset_and_remain_isolated() {
    let artifact = model("accumulate");
    let mut function = artifact.function(None, ComputeUnits::CpuOnly).unwrap();
    assert_eq!(
        function.description().states["memory"].default_shape,
        [2, 3]
    );
    let delta = Tensor::from_slice(&[2, 3], &[f16::ONE; 6]).unwrap();
    let mut inputs = Inputs::new();
    inputs.insert("delta", &delta).unwrap();
    assert!(matches!(
        function.predict(&inputs),
        Err(Error::StateRequired)
    ));
    let mut first = function.into_session();
    let mut second = artifact
        .function(None, ComputeUnits::CpuOnly)
        .unwrap()
        .into_session();
    let read = |prediction: ondevice_coreml::Prediction| {
        prediction
            .tensor::<f16>("output")
            .unwrap()
            .read()
            .into_data()
    };
    assert_eq!(read(first.predict(&inputs).unwrap()), [f16::ONE; 6]);
    assert_eq!(
        read(first.predict(&inputs).unwrap()),
        [f16::from_f32(2.); 6]
    );
    assert_eq!(read(second.predict(&inputs).unwrap()), [f16::ONE; 6]);
    first.reset();
    assert_eq!(read(first.predict(&inputs).unwrap()), [f16::ONE; 6]);
}

#[cfg(feature = "plan")]
#[test]
#[ignore = "requires generated Core ML fixtures"]
fn compute_plan_reports_operations_and_devices() {
    let artifact = model("affine");
    let plan =
        futures_lite::future::block_on(artifact.compute_plan(None, ComputeUnits::CpuOnly)).unwrap();
    assert!(!plan.operations.is_empty());
    assert!(
        plan.operations
            .iter()
            .any(|operation| !operation.supported_devices.is_empty())
    );
}
